import Link from "next/link";
import { patterns } from "@/lib/serial/patterns";

/**
 * Card grid generated by mapping over the pattern registry. Every card links to
 * the pattern's own `href` value from the registry, no URL is hardcoded here.
 * Values are not shown here (they require a sample size and confidence to be
 * shown honestly); the price guide carries them in full. Server Component.
 */
export function PatternGrid() {
  return (
    <ul className="pattern-grid grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
      {patterns.map((pattern) => {
        return (
          <li key={pattern.id} className="pattern-card card card-hover flex flex-col p-4">
            <div className="flex items-baseline justify-between gap-2">
              <Link href={pattern.href} className="link-accent text-base font-semibold">
                {pattern.name}
              </Link>
              <code className="rounded bg-zinc-100 px-1.5 py-0.5 font-mono text-xs text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300">
                {pattern.example}
              </code>
            </div>
            <p className="mt-2 flex-1 text-sm text-zinc-600 dark:text-zinc-400">
              {pattern.description}
            </p>
            <dl className="mt-3 space-y-1 text-xs text-zinc-500">
              <div className="flex justify-between gap-2">
                <dt>Rarity</dt>
                <dd className="text-right tabular-nums">{pattern.rarityOdds}</dd>
              </div>
            </dl>
          </li>
        );
      })}
    </ul>
  );
}
